-- Structure for app_ai_message
CREATE TABLE `app_ai_message` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `conversation_id` bigint NOT NULL,
  `role` varchar(32) NOT NULL COMMENT 'user/assistant/system',
  `content` mediumtext NOT NULL,
  `movie_id` bigint DEFAULT NULL COMMENT 'Primary recommended app_movie.id when applicable',
  `recommendation_reason` text COMMENT 'Recommendation explanation',
  `tokens_used` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ai_message_conversation_created` (`conversation_id`,`created_at`),
  KEY `idx_ai_message_movie` (`movie_id`),
  CONSTRAINT `fk_ai_message_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `app_ai_conversation` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=77 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI recommendation conversation message';

