  `poster_urls_csv` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '旧表海报串，保留兼容回放',
  `region_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区域',
  `region_id` bigint DEFAULT NULL COMMENT '规范地区引用；当前单地区能力落到 app_movie_region',
  `release_date` date DEFAULT NULL COMMENT '上映时间',
  `director_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '导演',
  `cast_names` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主演',
  `synopsis` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '剧情简介',
  `detail_html` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '电影详情 HTML',
  `like_count` int NOT NULL DEFAULT '0' COMMENT '点赞数',
  `dislike_count` int NOT NULL DEFAULT '0' COMMENT '点踩数',
  `click_count` int NOT NULL DEFAULT '0' COMMENT '点击次数',
  `comment_count` int NOT NULL DEFAULT '0' COMMENT '评论数',
  `favorite_count` int NOT NULL DEFAULT '0' COMMENT '收藏数',
  `total_score` double DEFAULT '0' COMMENT '累计评分',
  `last_clicked_at` datetime DEFAULT NULL COMMENT '最近点击时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_app_movie_legacy_id` (`legacy_dianyingxinxi_id`),
  KEY `idx_app_movie_type_id` (`movie_type_id`),
  KEY `idx_app_movie_title` (`title`),
  KEY `idx_app_movie_region_id` (`region_id`),
  CONSTRAINT `fk_app_movie_region_id` FOREIGN KEY (`region_id`) REFERENCES `app_movie_region` (`id`),
  CONSTRAINT `fk_app_movie_type_id` FOREIGN KEY (`movie_type_id`) REFERENCES `app_movie_type` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='phase-1 电影主表';

-- Data for app_movie
-- Exported rows: 50
INSERT INTO `app_movie` (`id`, `legacy_dianyingxinxi_id`, `movie_type_id`, `legacy_type_name`, `title`, `poster_urls_csv`, `region_name`, `region_id`, `release_date`, `director_name`, `cast_names`, `synopsis`, `detail_html`, `like_count`, `dislike_count`, `click_count`, `comment_count`, `favorite_count`, `total_score`, `last_clicked_at`, `created_at`, `updated_at`) VALUES ('2', '2', '2', '科幻', '流浪地球2', 'upload/movie_liulangdiqiu2.jpg', '大陆', '1', '2023-01-22', '郭帆', '吴京,刘德华,李雪健,沙溢', '太阳危机将至，人类启动行星发动机计划，推动地球离开太阳系。', '<p>《流浪地球2》是郭帆执导的2023年中国大陆科幻冒险灾难片，改编自刘慈欣小说《流浪地球》，由吴京、刘德华、李雪健、沙溢、宁理等出演。影片作为《流浪地球》的前传，围绕太阳危机、移山计划和数字生命等议题展开，展现人类在全球灾难前的协作、分歧与牺牲。</p><p>本片兼具硬科幻设定、灾难场面和群像叙事，适合作为科幻、冒险、灾难题材推荐页的重点影片；它的工业化视效与家国情感表达，也能为详情页提供较强的观影吸引点。</p>', 1, 0, 135, 3, 6, 4, '2026-04-25 21:53:05', '2026-04-25 11:30:14', '2026-05-10 15:10:36'), ('6', '-900000003', '9', '奇幻', '封神第一部：朝歌风云', 'upload/movie_fengshen1.jpg', '中国大陆', '2', '2023-07-20', '乌尔善', '费翔、李雪健、黄渤、于适', '少年英雄卷入封神大战并面对王权与宿命的冲突', '<p>《封神第一部：朝歌风云》是乌尔善执导的2023年中国大陆奇幻史诗电影，取材自《封神演义》和《武王伐纣平话》，由费翔、李雪健、黄渤、于适、陈牧驰、娜然等出演。故事聚焦商王殷寿、妲己、姜子牙、姬发等人物在朝歌权力漩涡中的抉择与对抗。</p><p>影片以古典神话为基础，结合战争、奇幻、宫廷权谋和英雄成长叙事，适合推荐给喜欢国产史诗、神话改编和大规模视效场面的观众。</p>', 388, 20, 4900, 118, 702, 8.4, NULL, '2026-04-26 14:26:17', '2026-05-09 13:25:21'), ('7', '-900000004', '10', '动画', '长安三万里', 'upload/movie_changan30000li.jpg', '中国大陆', '2', '2023-07-08', '谢君伟', '杨天翔、凌振赫、吴俊全', '高适回望盛唐群星并讲述李白与时代的诗意传奇', '<p>《长安三万里》是谢君伟、邹靖执导的2023年中国大陆历史动画电影，由追光动画制作，杨天翔、凌振赫、吴俊全、宣晓鸣等参与配音。影片以高适回望李白与盛唐群星的经历为主线，将诗歌、友情、理想与安史之乱后的历史变局交织呈现。</p><p>本片适合放入动画、历史、传统文化和家庭观影推荐场景；它以较长篇幅呈现唐诗意象和盛唐文人群像，能为详情页提供文化气质鲜明的介绍内容。</p>', 365, 9, 4600, 102, 640, 8.8, NULL, '2026-04-26 14:26:17', '2026-05-09 13:25:21'), ('8', '-900000005', '11', '剧情', '热辣滚烫', 'upload/movie_relaguntang.jpg', '中国大陆', '2', '2024-02-10', '贾玲', '贾玲、雷佳音、张小斐', '普通人在拳击与生活的双重磨砺中重新找回自我力量', '<p>《热辣滚烫》是贾玲执导并主演的2024年中国大陆喜剧剧情片，改编自日本电影《百元之恋》，雷佳音、张小斐、杨紫、沙溢等参演。影片讲述长期宅家的杜乐莹在离家、打工和接触拳击之后，逐步重新面对生活并寻找自我掌控感的故事。</p><p>影片将喜剧外壳与女性成长、身体训练和人生重启主题结合，适合推荐给偏好励志、情感和春节档大众喜剧的用户。</p>', 430, 18, 6200, 145, 910, 8.3, NULL, '2026-04-26 14:26:17', '2026-05-09 13:25:21'), ('9', '-900000006', '12', '悬疑', '满江红', 'upload/movie_manjianghong.jpg', '中国大陆', '2', '2023-01-22', '张艺谋', '沈腾、易烊千玺、张译、雷佳音', '一场密信追查把众人卷入宋代权谋迷局', '<p>《满江红》是张艺谋执导、张艺谋与陈宇编剧的2023年中国大陆历史悬疑喜剧片，沈腾、易烊千玺、张译、雷佳音、岳云鹏等主演。故事发生在南宋绍兴年间，围绕金国使者遇害和密信失踪展开，在宰相府一夜限时查案中层层反转。</p><p>影片以封闭空间、快节奏对白、悬疑推理和家国情绪形成主要看点，适合推荐给喜欢古装悬疑、群像表演和强情节反转的观众。</p>', 401, 22, 5100, 125, 760, 8.2, NULL, '2026-04-26 14:26:17', '2026-05-09 13:25:21'), ('10', '-900000007', '13', '喜剧', '你好，李焕英', 'upload/movie_nihaolihuanying.jpg', '中国大陆', '2', '2021-02-12', '贾玲', '贾玲、张小斐、沈腾、陈赫', '女儿跨越时空重新理解母亲的人生与爱', '<p>《你好，李焕英》是贾玲自编自导并主演的2021年中国大陆喜剧剧情片，张小斐、沈腾、陈赫、刘佳等出演，改编自贾玲同名小品及其个人情感经验。影片通过女儿意外回到母亲年轻时代的设定，讲述亲情、遗憾与理解。</p><p>本片以轻喜剧叙事承载母女情感，适合推荐给关注亲情、怀旧年代和春节档温情电影的用户；详情页可突出其真挚情感和大众共鸣。</p>', 455, 13, 5600, 138, 860, 8.6, NULL, '2026-04-26 14:26:17', '2026-05-09 13:25:21'), ('11', '-900000008', '2', '科幻', '独行月球', 'upload/movie_duxingyueqiu.jpg', '中国大陆', '2', '2022-07-29', '张吃鱼', '沈腾、马丽', '维修工被遗落月球后在孤独与希望之间寻找回家的路', '<p>《独行月球》是张吃鱼执导的2022年中国大陆科幻喜剧片，改编自韩国漫画家赵石的同名漫画，由沈腾、马丽领衔主演。故事设定在人类执行月盾计划抵御小行星危机时，维修工独孤月被意外遗留在月球，展开孤独又荒诞的求生经历。</p><p>影片将开心麻花式喜剧、科幻灾难设定和个人英雄叙事结合，适合作为喜剧、科幻和合家欢推荐内容，详情页可强调笑点与末日孤独感之间的反差。</p>', 350, 18, 4300, 96, 580, 7.9, NULL, '2026-04-26 14:26:17', '2026-05-09 13:25:21'), ('12', '-900000009', '10', '动画', '哪吒之魔童降世', 'upload/movie_nezha.jpg', '中国大陆', '2', '2019-07-26', '饺子', '吕艳婷、囧森瑟夫、瀚墨', '少年哪吒在偏见与命运中寻找自我认同', '<p>《哪吒之魔童降世》是饺子执导并编剧的2019年中国大陆动画电影，取材自《封神演义》相关神话，由吕艳婷、囧森瑟夫、瀚墨等参与配音。影片重塑哪吒、敖丙、李靖夫妇和太乙真人等角色，围绕“魔丸”身份与自我选择展开。</p><p>本片以高完成度国产动画、神话新编和“我命由我不由天”的成长主题形成推荐价值，适合面向动画、奇幻、亲子及国漫用户展示。</p>', 0, 0, 7300, 188, 1, 9.2, NULL, '2026-04-26 14:26:17', '2026-05-09 13:25:21'), ('13', '-900000010', '11', '剧情', '八角笼中', 'upload/movie_bajiaolongzhong.jpg', '中国大陆', '2', '2023-07-06', '王宝强', '王宝强、陈永胜、史彭元', '普通人带着孩子们在困境中寻找一条向上的路', '<p>《八角笼中》是王宝强执导并主演的2023年中国大陆剧情动作片，陈永胜、史彭元等出演。影片讲述向腾辉收留一群缺少照料的孩子，并试图通过格斗训练为他们寻找出路，却在舆论和现实困境中承受压力的故事。</p><p>影片关注困境儿童、体育训练和社会误解，兼具励志和现实题材属性，适合推荐给喜欢现实主义、人物成长和运动题材的用户。</p>', 298, 14, 3500, 88, 455, 7.7, NULL, '2026-04-26 14:26:17', '2026-05-09 13:25:21'), ('14', '-900000011', '12', '悬疑', '消失的她', 'upload/movie_xiaoshideta.jpg', '中国大陆', '2', '2023-06-22', '崔睿、刘翔', '朱一龙、倪妮、文咏珊', '一次离奇失踪牵出婚姻与真相背后的重重反转', '<p>《消失的她》是崔睿、刘翔执导，陈思诚监制的2023年中国大陆悬疑犯罪片，由朱一龙、倪妮、文咏珊、杜江主演。影片围绕何非寻找失踪妻子展开，当“妻子”突然出现却疑点重重时，真相逐渐牵出亲密关系、欺骗与欲望的黑暗面。</p><p>本片适合悬疑、犯罪、反转剧情和热门商业片推荐位，详情页可突出其高概念谜题、强反转结构和情感警示意味。</p>', 392, 17, 5400, 132, 820, 8.1, NULL, '2026-04-26 14:26:17', '2026-05-09 13:25:21'), ('17', '-900000012', '13', '喜剧', '飞驰人生2', 'upload/movie_feichirensheng2.jpg', '中国大陆', '2', '2024-02-10', '韩寒', '沈腾、范丞丞、尹正', '落魄车手重返赛道并再次挑战巴音布鲁克拉力赛', '<p>《飞驰人生2》是韩寒执导并编剧的2024年中国大陆喜剧运动片，沈腾、范丞丞、尹正、张本煜、孙艺洲等主演，是《飞驰人生》的续作。故事延续车手张驰的命运，在落魄之后重组车队，向最后一届巴音布鲁克拉力赛发起挑战。</p><p>影片结合赛车竞技、草台班子喜剧和中年再出发主题，适合推荐给喜欢运动燃点、团队成长和韩寒式幽默的观众。</p>', 0, 0, 5400, 126, 0, 8.1, NULL, '2026-04-26 14:49:42', '2026-05-09 13:25:21'), ('18', '-900000013', '11', '剧情', '热烈', 'upload/movie_relie.jpg', '中国大陆', '2', '2023-07-28', '大鹏', '黄渤、王一博、刘敏涛', '街舞团队在现实压力中重新点燃对舞台的热爱', '<p>《热烈》是大鹏执导并参与编剧的2023年中国大陆青春喜剧剧情片，由黄渤、王一博领衔主演。影片讲述资深街舞教练丁雷与怀抱职业舞者梦想的年轻人陈烁相遇后，在舞团训练、现实压力和舞台机会中共同成长。</p><p>本片以街舞竞技、青春追梦和师徒关系为主要看点，适合推荐给喜欢励志、体育舞蹈和热血舞台表达的用户。</p>', 298, 14, 3500, 88, 455, 7.7, NULL, '2026-04-26 14:49:42', '2026-05-09 13:25:21'), ('19', '-900000014', '10', '动画', '铃芽之旅', 'upload/movie_suzume.jpg', '日本', '3', '2023-03-24', '新海诚', '原菜乃华、松村北斗', '少女踏上关门旅程并与灾难记忆和解', '<p>《铃芽之旅》是新海诚编剧并执导的2022年日本动画奇幻冒险片，由原菜乃华、松村北斗、深津绘里等配音。故事讲述少女岩户铃芽与闭门师宗像草太相遇后，踏上关闭灾难之门、阻止地震灾厄的旅程。</p><p>影片延续新海诚作品中的青春、灾难、旅行和记忆主题，画面风格鲜明，适合推荐给动画、奇幻、青春成长和日本电影观众。</p>', 412, 11, 5200, 1, 790, 3, NULL, '2026-04-26 14:49:42', '2026-05-09 13:32:46'), ('20', '-900000015', '2', '科幻', '星际穿越', 'upload/movie_interstellar.jpg', '美国', '4', '2014-11-12', '克里斯托弗诺兰', '马修麦康纳、安妮海瑟薇、杰西卡查斯坦', '宇航员穿越虫洞为人类寻找新的栖居地', '<p>《星际穿越》是克里斯托弗·诺兰执导并参与编剧的2014年英美科幻电影，马修·麦康纳、安妮·海瑟薇、杰西卡·查斯坦、迈克尔·凯恩等主演。影片设定在粮食危机威胁人类生存的未来，讲述宇航员穿越虫洞寻找新家园的星际任务。</p><p>本片将硬科幻概念、亲情叙事、时间尺度和宏大视听结合，是科幻、冒险和经典电影推荐页的高适配内容。</p>', 520, 15, 6800, 166, 980, 9.4, NULL, '2026-04-26 14:49:42', '2026-05-09 13:25:21'), ('21', '-900000016', '10', '动画', '寻梦环游记', 'upload/movie_coco.jpg', '美国', '4', '2017-11-24', '李安克里奇', '安东尼冈萨雷斯、盖尔加西亚贝纳尔', '少年进入亡灵世界理解家人与记忆的意义', '<p>《寻梦环游记》是皮克斯动画工作室制作、李·昂克里奇和阿德里安·莫利纳执导的2017年美国动画奇幻音乐片，安东尼·冈萨雷斯、盖尔·加西亚·贝纳尔、本杰明·布拉特等配音。影片以墨西哥亡灵节文化为背景，讲述少年米格尔误入亡灵世界并追寻音乐梦想与家族真相的故事。</p><p>影片以音乐、亲情、记忆和文化尊重为核心，适合家庭、动画、音乐和高口碑经典推荐场景，详情页可突出“记住我”背后的亲情主题。</p>', 478, 7, 6100, 154, 930, 9.3, NULL, '2026-04-26 14:49:42', '2026-05-09 13:25:21'), ('22', '-900000017', '11', '剧情', '我不是药神', 'upload/movie_dyingtosurvive.jpg', '中国大陆', '2', '2018-07-05', '文牧野', '徐峥、周一围、王传君', '普通人因廉价救命药卷入现实困局与人性抉择', '<p>《我不是药神》是文牧野执导的2018年中国大陆剧情喜剧片，由徐峥、王传君、周一围、谭卓、章宇、杨新鸣等主演，灵感来自慢粒白血病患者陆勇代购抗癌药的真实事件。影片讲述保健品店老板程勇卷入印度仿制药代购后，在利益、法律与生命困境之间逐渐转变的故事。</p><p>本片具有强现实议题和社会讨论价值，适合推荐给关注现实主义、医疗伦理、人物救赎和高口碑国产电影的用户。</p>', 505, 12, 6400, 172, 1020, 9, NULL, '2026-04-26 14:49:42', '2026-05-09 13:25:21'), ('23', '-900000018', '11', '剧情', '让子弹飞', 'upload/movie_letbulletsfly.jpg', '中国大陆', '2', '2010-12-16', '姜文', '姜文、周润发、葛优', '悍匪与恶霸县长在乱世小城展开权谋对决', '<p>《让子弹飞》是姜文执导并主演的2010年中国大陆、香港合拍剧情动作喜剧片，葛优、周润发、刘嘉玲、陈坤等出演，改编自马识途小说《夜谭十记》中的《盗官记》。影片讲述土匪张麻子假扮县长进入鹅城，与地方恶霸黄四郎展开权力、财富与民心的博弈。</p><p>影片以黑色幽默、民国西部片气质、密集台词和多重隐喻著称，适合推荐给喜欢经典国产片、荒诞喜剧和强风格导演作品的观众。</p>', 468, 10, 5900, 149, 900, 8.8, NULL, '2026-04-26 14:49:42', '2026-05-09 13:25:21'), ('24', '-900000019', '14', '犯罪', '三大队', 'upload/movie_endlessjourney.jpg', '中国大陆', '2', '2023-12-15', '戴墨', '张译、李晨、魏晨', '警队成员多年追凶并在信念中完成未竟使命', '<p>《三大队》是戴墨执导、陈思诚监制的2023年中国大陆犯罪剧情片，由张译、李晨、魏晨、曹炳琨、王骁、张子贤主演，改编自深蓝纪实文学《请转告局长，三大队任务完成了》。故事讲述刑侦队长程兵入狱后仍以普通人身份追踪在逃嫌犯，完成横跨多年的执念追凶。</p><p>影片兼具犯罪类型、现实改编和人物信念表达，适合推荐给喜欢刑侦、追凶、公路式叙事和张译表演的用户。</p>', 344, 13, 3900, 97, 520, 7.8, NULL, '2026-04-26 14:49:42', '2026-05-09 13:25:21'), ('25', '-900000020', '14', '犯罪', '周处除三害', 'upload/movie_zhouchuchusanhai.jpg', '中国台湾', '5', '2023-10-06', '黄精甫', '阮经天、袁富华、陈以文', '通缉犯在追逐恶名与自我觉醒间踏上血色旅程', '<p>《周处除三害》是黄精甫编剧并执导的2023年中国台湾犯罪动作片，由阮经天、袁富华、陈以文、王净、李李仁、谢琼煖等主演。影片借用“周处除三害”典故，讲述通缉犯陈桂林误以为自己生命将尽，决定除掉通缉榜上排在自己前面的两名罪犯。</p><p>影片融合黑色幽默、犯罪动作、暴力美学和“贪嗔痴”隐喻，适合推荐给喜欢台港犯罪片、反英雄角色和高强度类型片的观众。</p>', 432, 16, 5700, 133, 860, 8.5, NULL, '2026-04-26 14:49:42', '2026-05-09 13:25:21'), ('26', '-900000021', '11', '剧情', '忠犬八公', 'upload/movie_hachiko_cn.jpg', '中国大陆', '2', '2023-03-31', '徐昂', '冯小刚、陈冲、白举纲', '一只忠犬陪伴家庭并用漫长守候诠释告别与忠诚', '<p>《忠犬八公》是徐昂执导的2023年中国大陆剧情片，由冯小刚、陈冲、白举纲、黄楚桐等主演，翻拍自日本电影《八公犬物语》。影片将经典忠犬故事本土化到重庆家庭语境中，讲述中华田园犬“八筒”与陈敬修一家相遇、陪伴和等待的故事。</p><p>本片适合家庭、宠物、温情和催泪剧情推荐场景；详情页可突出人与动物之间的陪伴、承诺和时间流逝带来的情感力量。</p>', 318, 9, 3600, 84, 470, 7.6, NULL, '2026-04-26 14:49:42', '2026-05-09 13:25:21'), ('27', NULL, '14', '犯罪', '教父', 'https://upload.wikimedia.org/wikipedia/en/1/1c/The_Godfather_%281972%29_poster.jpg', '美国', '4', '1972-03-24', '弗朗西斯·福特·科波拉', '马龙·白兰度 / 阿尔·帕西诺 / 詹姆斯·凯恩', '维托·柯里昂领导的黑手党家族在权力更迭与家族责任之间经历残酷考验，迈克尔也在动荡中一步步走向核心权力。', '<p>维托·柯里昂领导的黑手党家族在权力更迭与家族责任之间经历残酷考验，迈克尔也在动荡中一步步走向核心权力。</p>', 0, 0, 0, 0, 0, 0, NULL, '2026-05-09 18:51:01', '2026-05-09 20:34:11'), ('28', NULL, '14', '犯罪', '教父2', 'https://upload.wikimedia.org/wikipedia/en/0/03/Godfather_part_ii.jpg', '美国', '4', '1974-12-20', '弗朗西斯·福特·科波拉', '阿尔·帕西诺 / 罗伯特·德尼罗 / 黛安·基顿', '影片交织展现年轻维托的崛起与迈克尔在家族事业中的孤独扩张，描绘柯里昂家族两代教父的命运轨迹。', '<p>影片交织展现年轻维托的崛起与迈克尔在家族事业中的孤独扩张，描绘柯里昂家族两代教父的命运轨迹。</p>', 0, 0, 0, 0, 0, 0, NULL, '2026-05-09 18:51:01', '2026-05-09 20:34:11'), ('29', NULL, '11', '剧情', '黑暗骑士', 'https://upload.wikimedia.org/wikipedia/commons/a/a3/The_Dark_Knight_movie_poster_-_censored_copyright.jpg', '美国', '4', '2008-07-18', '克里斯托弗·诺兰', '克里斯蒂安·贝尔 / 希斯·莱杰 / 艾伦·艾克哈特', '蝙蝠侠与盟友试图清除哥谭犯罪势力，却因小丑的极端混乱计划而被迫直面正义与牺牲的代价。', '<p>蝙蝠侠与盟友试图清除哥谭犯罪势力，却因小丑的极端混乱计划而被迫直面正义与牺牲的代价。</p>', 0, 0, 0, 0, 0, 0, NULL, '2026-05-09 18:51:01', '2026-05-09 20:34:11'), ('30', NULL, '11', '剧情', '霸王别姬', 'https://upload.wikimedia.org/wikipedia/en/c/c5/Farewell_My_Concubine_poster.jpg', '中国', '6', '1993-07-26', '陈凯歌', '张国荣 / 巩俐 / 张丰毅', '两位京剧伶人与一位女子在半个世纪的时代激流中纠缠沉浮，舞台与人生彼此映照，留下深刻悲剧。', '<p>两位京剧伶人与一位女子在半个世纪的时代激流中纠缠沉浮，舞台与人生彼此映照，留下深刻悲剧。</p>', 0, 0, 0, 0, 0, 0, NULL, '2026-05-09 18:51:01', '2026-05-09 2