-- Structure for app_movie_comment
CREATE TABLE `app_movie_comment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `legacy_discussdianyingxinxi_id` bigint DEFAULT NULL COMMENT '旧表 discussdianyingxinxi.id',
  `movie_id` bigint DEFAULT NULL COMMENT '关联 app_movie.id',
  `user_id` bigint DEFAULT NULL COMMENT '关联 app_user.id',
  `legacy_refid` bigint NOT NULL COMMENT '旧表 refid',
  `legacy_userid` bigint NOT NULL COMMENT '旧表 userid',
  `author_avatar_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '评论时头像快照',
  `author_name_snapshot` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '评论时昵称快照',
  `content_html` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评论内容',
  `rating` double DEFAULT NULL COMMENT '评分',
  `reply_html` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '回复内容',
  `like_count` int NOT NULL DEFAULT '0' COMMENT '赞数量',
  `dislike_count` int NOT NULL DEFAULT '0' COMMENT '踩数量',
  `is_pinned` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否置顶',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_app_movie_comment_legacy_id` (`legacy_discussdianyingxinxi_id`),
