-- Structure for app_movie_person_rel
CREATE TABLE `app_movie_person_rel` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `movie_id` bigint NOT NULL COMMENT '关联 app_movie.id',
  `person_id` bigint NOT NULL COMMENT '关联 app_movie_person.id',
  `relation_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'director / cast',
  `sort_order` int NOT NULL DEFAULT '1' COMMENT '展示顺序，从 1 开始',
  `person_name_snapshot` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关系来源的人名快照',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_app_movie_person_rel_movie_role_person` (`movie_id`,`relation_type`,`person_id`),
  KEY `idx_app_movie_person_rel_person_id` (`person_id`),
  KEY `idx_app_movie_person_rel_role_sort` (`movie_id`,`relation_type`,`sort_order`),
  CONSTRAINT `fk_app_movie_person_rel_movie_id` FOREIGN KEY (`movie_id`) REFERENCES `app_movie` (`id`),
  CONSTRAINT `fk_app_movie_person_rel_person_id` FOREIGN KEY (`person_id`) REFERENCES `app_movie_person` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='runtime 电影-人物关系表';

