-- Structure for app_user_movie_action
CREATE TABLE `app_user_movie_action` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `legacy_storeup_id` bigint DEFAULT NULL COMMENT '旧表 storeup.id',
  `user_id` bigint DEFAULT NULL COMMENT '关联 app_user.id',
  `movie_id` bigint DEFAULT NULL COMMENT '关联 app_movie.id',
  `legacy_userid` bigint NOT NULL COMMENT '旧表 userid',
  `legacy_refid` bigint DEFAULT NULL COMMENT '旧表 refid',
  `legacy_tablename` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '旧表 tablename',
  `action_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'favorite / like / dislike / legacy_unknown:*',
  `target_name_snapshot` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标名称快照',
  `target_picture_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '目标图片快照',
  `recommend_type` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '推荐类型',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_app_user_movie_action_legacy_id` (`legacy_storeup_id`),
  KEY `idx_app_user_movie_action_user_id` (`user_id`),
  KEY `idx_app_user_movie_action_movie_id` (`movie_id`),
  KEY `idx_app_user_movie_action_type` (`action_type`),
  CONSTRAINT `fk_app_user_movie_action_movie_id` FOREIGN KEY (`movie_id`) REFERENCES `app_movie` (`id`),
  CONSTRAINT `fk_app_user_movie_action_user_id` FOREIGN KEY (`user_id`) REFERENCES `app_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=19827 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='phase-1 用户电影行为表';

